"""Shared helpers for compress.py / decompress.py.

The resharded layout is:

    <out>/manifest.json          -- describes the shard stream
    <out>/data/...               -- shard parts, nested so that no directory
                                    ever holds more than MAX_ENTRIES children

The payload is a single tar stream (which captures the exact original file
names, contents, ordering and directory structure), piped through a streaming
compressor and split into fixed-size parts.  Splitting the *compressed* stream
guarantees the per-file size cap regardless of how large individual source
files are.
"""

import hashlib
import inspect
import json
import os

MANIFEST_NAME = "manifest.json"
DATA_DIR_NAME = "data"
FORMAT = "reshard-v1"

# Hard constraints of the target layout.
MAX_ENTRIES = 30                 # max files/folders per directory
MAX_PART_BYTES = 15 * 1000 * 1000  # max bytes per file

# Headroom below the hard cap (parts are flushed at this size).
PART_BYTES = 12 * 1000 * 1000

ZSTD_LEVEL = 10


# --------------------------------------------------------------------------
# codecs (public APIs only, with runtime feature detection)
# --------------------------------------------------------------------------
def _zstd():
    try:
        import zstandard
    except ImportError:
        return None
    return zstandard


def _call_with_optional(func, kwargs, *args):
    """Call ``func`` passing only the keyword arguments it accepts."""
    try:
        params = inspect.signature(func).parameters
    except (TypeError, ValueError):
        params = None
    if params is not None and not any(
        p.kind is inspect.Parameter.VAR_KEYWORD for p in params.values()
    ):
        kwargs = {k: v for k, v in kwargs.items() if k in params}
    while True:
        try:
            return func(*args, **kwargs)
        except TypeError:
            if not kwargs:
                raise
            kwargs.pop(next(iter(kwargs)))


def open_compressor(fobj):
    """Return (writable stream, codec name).  Closing the stream flushes it."""
    zstandard = _zstd()
    if zstandard is not None:
        cctx = _call_with_optional(
            zstandard.ZstdCompressor, {"level": ZSTD_LEVEL, "threads": -1}
        )
        stream = _call_with_optional(
            cctx.stream_writer, {"closefd": False}, fobj
        )
        return stream, "zstd"
    import lzma

    return lzma.LZMAFile(fobj, "wb", preset=6), "xz"


def open_decompressor(fobj, codec):
    """Return a readable stream of the original tar bytes."""
    if codec == "zstd":
        zstandard = _zstd()
        if zstandard is None:
            raise RuntimeError(
                "the 'zstandard' package is required to read this archive"
            )
        dctx = zstandard.ZstdDecompressor()
        return _call_with_optional(dctx.stream_reader, {"closefd": False}, fobj)
    if codec == "xz":
        import lzma

        return lzma.LZMAFile(fobj, "rb")
    raise RuntimeError("unknown codec %r" % (codec,))


# --------------------------------------------------------------------------
# split writer / concatenating reader
# --------------------------------------------------------------------------
class SplitWriter(object):
    """File-like sink that spills its input into fixed-size numbered parts."""

    def __init__(self, staging_dir, limit=PART_BYTES):
        self.dir = staging_dir
        self.limit = limit
        self.parts = []          # list of (filename, size)
        self._fh = None
        self._written = 0
        self.digest = hashlib.sha256()
        os.makedirs(staging_dir, exist_ok=True)

    def _rotate(self):
        self._close_part()
        name = "%08d.part" % len(self.parts)
        self.parts.append([name, 0])
        self._fh = open(os.path.join(self.dir, name), "wb")
        self._written = 0

    def _close_part(self):
        if self._fh is not None:
            self._fh.close()
            self.parts[-1][1] = self._written
            self._fh = None

    def write(self, data):
        view = memoryview(data)
        total = len(view)
        self.digest.update(view)
        while view:
            if self._fh is None or self._written >= self.limit:
                self._rotate()
            room = self.limit - self._written
            chunk = view[:room]
            self._fh.write(chunk)
            self._written += len(chunk)
            view = view[len(chunk):]
        return total

    def flush(self):
        if self._fh is not None:
            self._fh.flush()

    def tell(self):
        return sum(p[1] for p in self.parts[:-1]) + self._written

    def close(self):
        self._close_part()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


class ConcatReader(object):
    """File-like source that reads a list of files as one continuous stream."""

    def __init__(self, paths):
        self.paths = list(paths)
        self._idx = 0
        self._fh = None

    def _next(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        if self._idx >= len(self.paths):
            return False
        self._fh = open(self.paths[self._idx], "rb")
        self._idx += 1
        return True

    def readable(self):
        return True

    def read(self, size=-1):
        out = []
        remaining = size
        while remaining is None or remaining < 0 or remaining > 0:
            if self._fh is None and not self._next():
                break
            chunk = self._fh.read(-1 if (remaining is None or remaining < 0)
                                  else remaining)
            if not chunk:
                if not self._next():
                    break
                continue
            out.append(chunk)
            if remaining is not None and remaining >= 0:
                remaining -= len(chunk)
        return b"".join(out)

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


# --------------------------------------------------------------------------
# layout
# --------------------------------------------------------------------------
def layout_depth(num_parts, fanout=MAX_ENTRIES):
    """Smallest nesting depth such that `num_parts` fit with <= fanout each."""
    depth = 1
    capacity = fanout
    while capacity < max(num_parts, 1):
        capacity *= fanout
        depth += 1
    return depth


def part_relpath(index, depth, fanout=MAX_ENTRIES):
    """Relative path (posix style) of part `index` inside the data directory."""
    digits = []
    value = index
    for _ in range(depth):
        digits.append(value % fanout)
        value //= fanout
    digits.reverse()
    dirs = ["%02d" % d for d in digits[:-1]]
    name = "part-%06d.bin" % index
    return "/".join(dirs + [name])


def read_manifest(path):
    with open(path, "r") as fh:
        return json.load(fh)


def write_manifest(path, payload):
    with open(path, "w") as fh:
        json.dump(payload, fh, indent=1, sort_keys=True)
        fh.write("\n")

