import hashlib
import inspect
import json
import os
import sys


def ensure_venv():
    """Re-exec inside the project's uv venv if dependencies are missing here."""
    try:
        import zstandard  # noqa: F401
    except ImportError:
        pass
    else:
        return
    here = os.path.dirname(os.path.abspath(__file__))
    for candidate in (
        os.path.join(here, ".venv", "bin", "python"),
        os.path.join(here, ".venv", "bin", "python3"),
    ):
        if os.path.exists(candidate) and os.path.realpath(
            candidate
        ) != os.path.realpath(sys.executable):
            os.environ["RESHARD_NO_REEXEC"] = "1"
            os.execv(candidate, [candidate] + sys.argv)
